import re

def remove_multiple_spaces(s: str) -> str:
    return re.sub(r'\s+', ' ', s)

def is_Two_Alter(s):
    if len(s) < 2:
        return False
    # The string should contain exactly two distinct characters
    chars = set(s)
    if len(chars) != 2:
        return False
    # Check if characters alternate
    for i in range(len(s) - 1):
        if s[i] == s[i + 1]:
            return False
    return True

